'use strict';
const crypto = require('node:crypto');
const { EventEmitter } = require('node:events');

const GUID = '258EAFA5-E914-47DA-95CA-C5AB0DC85B11';

// builds one unmasked server frame (FIN set)
function frame(opcode, payload) {
  const len = payload.length;
  let head;
  if (len < 126) {
    head = Buffer.from([0x80 | opcode, len]);
  } else if (len < 65536) {
    head = Buffer.alloc(4);
    head[0] = 0x80 | opcode; head[1] = 126; head.writeUInt16BE(len, 2);
  } else {
    head = Buffer.alloc(10);
    head[0] = 0x80 | opcode; head[1] = 127; head.writeBigUInt64BE(BigInt(len), 2);
  }
  return Buffer.concat([head, payload]);
}

class WsClient extends EventEmitter {
  constructor(req, socket) {
    super();
    this.socket = socket;
    this.url = req.url;
    this.query = new URL(req.url, 'http://x').searchParams;
    this.isOpen = true;
    this.buf = Buffer.alloc(0);
    this.parts = [];
    this.partOp = 0;
    socket.setNoDelay(true);
    socket.on('data', d => this._data(d));
    const end = () => { if (this.isOpen) { this.isOpen = false; this.emit('close'); } };
    socket.on('close', end);
    socket.on('end', end);
    socket.on('error', end);
  }
  get bufferedAmount() { return this.socket.writableLength; }
  _send(op, payload) {
    if (!this.isOpen) return false;
    this.socket.write(frame(op, payload));
    return true;
  }
  sendText(s) { return this._send(1, Buffer.from(String(s), 'utf8')); }
  sendBinary(b) { return this._send(2, Buffer.isBuffer(b) ? b : Buffer.from(b.buffer, b.byteOffset, b.byteLength)); }
  close(code = 1000) {
    if (!this.isOpen) return;
    const p = Buffer.alloc(2); p.writeUInt16BE(code, 0);
    try { this.socket.write(frame(8, p)); } catch (e) { /* socket gone */ }
    this.isOpen = false;
    this.socket.end();
    this.emit('close');
  }
  // parses client frames (always masked); handles fragmentation, ping and close
  _data(d) {
    this.buf = Buffer.concat([this.buf, d]);
    for (;;) {
      const b = this.buf;
      if (b.length < 2) return;
      const fin = b[0] & 0x80, op = b[0] & 0x0f, masked = b[1] & 0x80;
      let len = b[1] & 0x7f, pos = 2;
      if (len === 126) { if (b.length < 4) return; len = b.readUInt16BE(2); pos = 4; }
      else if (len === 127) { if (b.length < 10) return; len = Number(b.readBigUInt64BE(2)); pos = 10; }
      if (len > 1 << 20) { this.close(1009); return; }  // 1 MB is plenty for a WLED client
      const mpos = pos; if (masked) pos += 4;
      if (b.length < pos + len) return;
      let payload = Buffer.from(b.subarray(pos, pos + len));
      if (masked) for (let i = 0; i < len; i++) payload[i] ^= b[mpos + (i & 3)];
      this.buf = b.subarray(pos + len);
      if (op === 8) { this.close(1000); return; }
      if (op === 9) { this._send(10, payload); continue; }  // ping -> pong
      if (op === 10) continue;
      if (op === 0 || op === 1 || op === 2) {
        if (op !== 0) { this.partOp = op; this.parts = []; }
        this.parts.push(payload);
        if (!fin) continue;
        const msg = Buffer.concat(this.parts); this.parts = [];
        if (this.partOp === 1) this.emit('text', msg.toString('utf8'));
        else this.emit('binary', msg);
      }
    }
  }
}

function acceptUpgrade(req, socket) {
  const key = req.headers['sec-websocket-key'];
  if (!key || String(req.headers.upgrade || '').toLowerCase() !== 'websocket') {
    socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
    return null;
  }
  const accept = crypto.createHash('sha1').update(key + GUID).digest('base64');
  socket.write('HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n' +
    'Sec-WebSocket-Accept: ' + accept + '\r\n\r\n');
  return new WsClient(req, socket);
}

// refuses an upgrade with an HTTP status (e.g. 403 for a wrong key, 404 for an unknown path)
function refuseUpgrade(socket, status = 404) {
  socket.end('HTTP/1.1 ' + status + ' Refused\r\nConnection: close\r\nContent-Length: 0\r\n\r\n');
}

